async function preview(saved){if(!$('preview'))return;const seq=++previewSeq;const url=`${base}/fara-admin/design.php?action=preview&id=${encodeURIComponent(id)}`;const r=await fetch(url,saved?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Editor-Token':token},body:JSON.stringify({version:entity.version,document:doc})});const text=await r.text();if(!r.ok){try{throw Error(JSON.parse(text).error)}catch(e){throw Error(e.message||'پیش‌نمایش آماده نشد.')}}if(seq!==previewSeq||!$('preview'))return;const html=new DOMParser().parseFromString(text,'text/html');const b=html.createElement('base');b.href=location.origin+base+'/'+(doc.href||'index.html');html.head.prepend(b);const frame=$('preview');frame.onload=()=>{try{frame.contentDocument.addEventListener('click',e=>{e.preventDefault();const target=e.target.closest('[data-design-id]');if(target){selected=target.dataset.designId;editor()}else{const text=e.target.closest('[data-editor-fields]');if(text){const keys=JSON.parse(text.dataset.editorFields),field=[...document.querySelectorAll('[data-editor-field]')].find(x=>keys.includes(x.dataset.editorField));if(field){$('existing-texts').open=true;field.focus();field.scrollIntoView({block:'center',behavior:'smooth'})}}}})}catch{}};frame.srcdoc='<!doctype html>'+html.documentElement.outerHTML;$('preview-label').textContent=saved?'پیش‌نویس ذخیره‌شده':'دادهٔ جاری '+(dirty?'· ذخیره‌نشده':'· برابر با ذخیره')}
function collection(root){const box=h('section',null,{className:'card'});root.append(box);box.append(h('p','ذخیره فقط پیش‌نویس را تغییر می‌دهد؛ برای اعمال عمومی، انتشار را بزنید.'));if(id==='patterns')box.append(h('p','الگوها مستقل‌اند. درج الگو، یک کپی قابل ویرایش می‌سازد؛ تغییر الگو به کپی‌های قبلی منتقل نمی‌شود.'));
 doc.items.forEach((x,i)=>{const card=h('article',null,{className:'card'});box.append(card);input(card,id==='menu'?'عنوان لینک':'عنوان',x.label??x.title,v=>change(()=>x[id==='menu'?'label':'title']=v));if(id==='menu')input(card,'مقصد معتبر',x.href,v=>change(()=>x.href=v));if(id==='categories'){input(card,'شناسهٔ پایدار',x.id,v=>change(()=>x.id=v));select(card,'والد',x.parent,{'':'بدون والد',...Object.fromEntries(doc.items.filter(y=>y!==x).map(y=>[y.id,y.title]))},v=>change(()=>x.parent=v));input(card,'ترتیب',x.order,v=>change(()=>x.order=Number(v)),'number');check(card,'فعال',x.active,v=>change(()=>x.active=v))}
 if(id==='patterns')card.append(btn('درج در صفحه',async()=>{const dest=prompt('شناسهٔ صفحهٔ مقصد (مثلاً home)');if(!dest)return;const p=await api('get',dest);const bs=clone(x.blocks);rekey(bs);await api('save',dest,{version:p.entity.version,document:{...p.entity.draft,blocks:[...p.entity.draft.blocks,...bs]}});status('کپی مستقل الگو در پیش‌نویس صفحه درج شد.')}));
 row(card,btn('↑',()=>change(()=>{if(i>0)[doc.items[i-1],doc.items[i]]=[doc.items[i],doc.items[i-1]]},true)),btn('↓',()=>change(()=>{if(i<doc.items.length-1)[doc.items[i+1],doc.items[i]]=[doc.items[i],doc.items[i+1]]},true)),btn(id==='categories'?'غیرفعال کردن':'حذف',()=>change(()=>{if(id==='categories')x.active=false;else doc.items.splice(i,1)},true)));
 });box.append(btn('＋ افزودن گزینه',()=>change(()=>doc.items.push(id==='menu'?{label:'پیوند جدید',href:'index.html'}:id==='categories'?{id:'category-'+Date.now(),title:'حوزهٔ جدید',parent:'',active:true,order:doc.items.length}:{title:'الگوی جدید',blocks:[]}),true)));if(id==='patterns'){const f=h('input',null,{type:'file',accept:'application/json'});f.onchange=async()=>{try{const file=f.files[0];if(file.size>2e6)throw Error('فایل بزرگ است.');const imported=JSON.parse(await file.text());if(imported.format!=='fara-design-v1')throw Error('قالب نامعتبر');change(()=>doc.items.push({title:imported.document.title||'الگوی واردشده',blocks:imported.document.blocks}),true)}catch(e){error(e)}};label('ساخت الگو از خروجی طرح',f,box)}const history=h('details');history.append(h('summary','تاریخچه و بازیابی'));entity.history.forEach((r,i)=>history.prepend(btn(r.at+' · '+r.by+' · بازیابی',async()=>{if(dirty)throw Error('ابتدا ذخیره کنید.');await api('revision',id,{version:entity.version,revision:i});await open(id)})));box.append(history);buttons()}
function mediaView(){const root=$('content');const search=h('input',null,{type:'search',placeholder:'جست‌وجوی عنوان، alt یا شناسهٔ تصویر',ariaLabel:'جست‌وجوی رسانه'});root.append(search);search.oninput=()=>{for(const c of root.querySelectorAll('.media-grid article'))c.hidden=!c.textContent.includes(search.value)};root.append(h('p','فایل اصلی حفظ می‌شود؛ رسانهٔ استفاده‌نشده فقط برای کاربران مجاز پنل قابل مشاهده است.'),btn('＋ آپلود تصویر',()=>uploadDialog('library')));const grid=h('div',null,{className:'media-grid'});root.append(grid);for(const [key,m] of Object.entries(media)){const c=h('article',null,{className:'card'});c.append(h('img',null,{src:`${base}/fara-admin/design.php?media=${key}`,alt:m.alt}),h('h3',m.title||'تصویر بدون عنوان'),h('small',`${m.width} × ${m.height}`),h('p',m.alt));const title=input(c,'عنوان',m.title,()=>{}),alt=input(c,'متن جایگزین',m.alt,()=>{});c.append(btn('ذخیرهٔ مشخصات کتابخانه',async()=>{await api('media-meta','',{media:key,title:title.value,alt:alt.value});status('مشخصات کتابخانه ذخیره شد؛ alt هر بلوک مستقل است.')}));grid.append(c)}status(`${Object.keys(media).length} تصویر در کتابخانهٔ خصوصی`)}
function uploadDialog(destination,block=''){const dlg=h('dialog'),form=h('div');dlg.append(h('h2','این تصویر برای کجای سایت است؟'),form);let dest=destination,operation=block?'replace':'add';select(form,'محل استفاده',dest,{library:'فقط کتابخانه',block:'صفحه / بلوک مشخص',header:'سربرگ مشترک',footer:'مجموعهٔ تصاویر پابرگ',existing:'جایگزینی تصویر موجود سایت (مشترک)'},v=>dest=v);const asset=select(form,'تصویر موجود برای جایگزینی','',{'':'انتخاب تصویر',...Object.fromEntries(assets.map(a=>[a.id,(a.label||a.id)+' · '+a.pages.join('،')]))},()=>{});const page=input(form,'شناسهٔ صفحهٔ مقصد',id||'home',()=>{}),target=input(form,'شناسهٔ بلوک برای جایگزینی',block,()=>{});select(form,'عملیات',operation,{add:'افزودن تصویر مستقل',replace:'جایگزینی تصویر بلوک انتخاب‌شده'},v=>operation=v);form.append(h('p','جایگزینی فقط همان بلوک را تغییر می‌دهد. انتشار سربرگ/پابرگ در همهٔ صفحه‌ها اثر دارد.',{className:'hint'}));const title=input(form,'عنوان تصویر','',()=>{}),alt=input(form,'متن جایگزین','',()=>{}),file=h('input',null,{type:'file',accept:'image/png,image/jpeg,image/webp'}),img=h('img',null,{style:'max-width:100%;max-height:200px'});label('تصویر PNG / JPEG / WebP، حداکثر ۱۰ مگابایت',file,form);file.onchange=()=>{if(file.files[0]){if(img.src.startsWith('blob:'))URL.revokeObjectURL(img.src);img.src=URL.createObjectURL(file.files[0])}};form.append(img,btn('آپلود به پیش‌نویس',async()=>{if(dirty)throw Error('ابتدا طرح فعلی را ذخیره کنید.');const f=file.files[0];if(!f||f.size>10*1024*1024)throw Error('تصویر معتبر تا ۱۰ مگابایت انتخاب کنید.');const buf=new Uint8Array(await f.arrayBuffer());let bin='';for(let i=0;i<buf.length;i+=8192)bin+=String.fromCharCode(...buf.subarray(i,i+8192));const key=dest==='block'?page.value:dest==='library'?'home':'shared';const e=dest==='library'?null:(await api('get',key)).entity;await api('upload',key,{destination:dest,operation,asset:asset.value,block:target.value,version:e?.version,base64:btoa(bin),title:title.value,alt:alt.value});dlg.close();dlg.remove();await refresh();if(entity)await open(id);else{rootClear();mediaView()}status('تصویر در محل انتخاب‌شده به‌صورت پیش‌نویس ذخیره شد.')}),btn('انصراف',()=>{dlg.close();dlg.remove()}));document.body.append(dlg);dlg.showModal()}
function rootClear(){$('content').replaceChildren()}
async function permissions(){if(user.role!=='admin')throw Error('این بخش فقط برای مدیر است.');const d=await api('permissions',''),root=$('content');for(const u of d.users.filter(x=>x.role!=='admin')){const c=h('section',null,{className:'card permissions'}),p=clone(u.permissions);c.append(h('h2',u.username));const pass=input(c,'رمز فعلی مدیر برای اعمال مجوز','',()=>{},'password');for(const [cap,t]of Object.entries({text:'ویرایش متن',blocks:'ویرایش بلوک و طرح',media:'کتابخانه و آپلود رسانه',menu:'مدیریت منو',shared:'ظاهر مشترک',categories:'حوزه‌های فعالیت',create:'ساخت صفحه (بدون دسترسی خودکار)',publish:'انتشار و لغو انتشار'}))check(c,t,p[cap],v=>p[cap]=v);c.append(h('h3','صفحه‌های مجاز'));for(const page of list)check(c,page.title,p.pages?.includes(page.id),v=>p.pages=v?[...(p.pages||[]),page.id]:(p.pages||[]).filter(x=>x!==page.id));c.append(btn('اعمال و ابطال نشست‌های قبلی',async()=>{await api('permissions','',{user:u.id,password:pass.value,permissions:p});pass.value='';status('مجوزها ذخیره و نشست‌های قبلی کاربر باطل شد.')}));root.append(c)}if(!d.users.some(x=>x.role!=='admin'))root.append(h('p','ابتدا از «حساب‌های طراحی» یک طراح بسازید.'));status('مجوز صفحه و عملیات مستقل است؛ ساخت صفحه اجازهٔ ویرایش یا انتشار نمی‌دهد.')}
$('save').onclick=()=>save().catch(error);$('publish').onclick=()=>action('publish').catch(error);$('undo-local').onclick=()=>{if(!undo.length)return;redo.push(clone(doc));doc=undo.pop();dirty=true;editor()};$('redo-local').onclick=()=>{if(!redo.length)return;undo.push(clone(doc));doc=redo.pop();dirty=true;editor()};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view).catch(error));window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});setInterval(()=>{if(autosave&&dirty&&!busy)save().catch(error)},30000);
function commands(){const dlg=$('command-dialog');const draw=()=>{const root=$('command-results');root.replaceChildren();const cmds=[...Object.entries(titles).map(([v,t])=>[t,()=>navigate(v)]),...list.map(p=>[p.title,()=>open(p.id)]),['ذخیرهٔ پیش‌نویس',save],['انتشار',()=>action('publish')]];for(const [t,fn]of cmds.filter(([t])=>t.includes($('command-search').value)))root.append(btn(t,()=>{dlg.close();return fn()}))};$('command-search').oninput=draw;draw();dlg.showModal();$('command-search').focus()}
$('commands').onclick=commands;$('close-commands').onclick=()=>$('command-dialog').close();document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();save().catch(error)}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();commands()}});navigate('pages').catch(error);
